632     if (!Elem.Assume)
633       continue;
634 
635     AssumeInst *I = cast<AssumeInst>(Elem.Assume);
636     assert(I->getFunction() == Q.CxtI->getFunction() &&
637            "Got assumption for the wrong function!");
638 
